using Alterverse.Characters;using UnityEngine;
namespace Alterverse.Combat
{
public sealed class CentralHealingPickup:MonoBehaviour
{
[SerializeField]private float radius=1.5f,healPercent=.286f,respawnSeconds=22f;private Transform visual,plus;private float readyAt;private bool available=true;private Material greenMat,stoneMat;
private void Start(){BuildVisual();}
private void Update(){if(Time.timeScale<=0f)return;if(!available){if(Time.time>=readyAt){available=true;if(plus!=null)plus.gameObject.SetActive(true);}return;}foreach(TeamMember member in FindObjectsByType<TeamMember>()){if(member==null)continue;Health h=member.GetComponent<Health>();if(h==null||h.IsDead||h.Normalized>=.995f)continue;Vector3 d=member.transform.position-transform.position;d.y=0;if(d.sqrMagnitude<=radius*radius){h.Heal(h.Max*healPercent);available=false;readyAt=Time.time+respawnSeconds;if(plus!=null)plus.gameObject.SetActive(false);break;}}if(plus!=null&&plus.gameObject.activeSelf){float pulse=1f+Mathf.Sin(Time.time*3.6f)*.10f;plus.localScale=Vector3.one*pulse;plus.localPosition=new Vector3(0,1.22f+Mathf.Sin(Time.time*2.4f)*.08f,0);}}
private void BuildVisual(){visual=new GameObject("DF_HealStation").transform;visual.SetParent(transform,false);greenMat=MakeMaterial(new Color(.02f,1f,.12f,1f),true);stoneMat=MakeMaterial(new Color(.18f,.23f,.30f),false);BuildPedestal();plus=new GameObject("DF_HealingPlus").transform;plus.SetParent(visual,false);plus.localPosition=new Vector3(0,1.22f,0);Part(plus,"Vertical",Vector3.zero,new Vector3(.24f,.88f,.24f),greenMat);Part(plus,"Horizontal",Vector3.zero,new Vector3(.88f,.24f,.24f),greenMat);}
private void BuildPedestal(){const int segments=8;for(int i=0;i<segments;i++){float a=i*Mathf.PI*2f/segments;Transform segment=Part(visual,"PedestalSegment",new Vector3(Mathf.Cos(a)*.72f,.12f,Mathf.Sin(a)*.72f),new Vector3(.58f,.24f,.42f),stoneMat);segment.localRotation=Quaternion.Euler(0,-a*Mathf.Rad2Deg+90f,0);Transform strip=Part(segment,"EnergyStrip",new Vector3(0,.02f,-.225f),new Vector3(.30f,.055f,.035f),greenMat);}Part(visual,"Core",new Vector3(0,.08f,0),new Vector3(.82f,.14f,.82f),stoneMat);Part(visual,"CoreGlow",new Vector3(0,.16f,0),new Vector3(.48f,.025f,.48f),greenMat);}
private Transform Part(Transform parent,string n,Vector3 p,Vector3 scale,Material mat){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name="DF_Heal"+n;g.transform.SetParent(parent,false);g.transform.localPosition=p;g.transform.localScale=scale;Collider c=g.GetComponent<Collider>();if(c!=null)c.enabled=false;Renderer r=g.GetComponent<Renderer>();if(r!=null)r.sharedMaterial=mat;return g.transform;}
private Material MakeMaterial(Color color,bool emissive){Shader shader=Shader.Find("Universal Render Pipeline/Lit");if(shader==null)shader=Shader.Find("Standard");Material m=new Material(shader);m.color=color;if(emissive){m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",color*4.5f);if(m.HasProperty("_BaseColor"))m.SetColor("_BaseColor",color);}return m;}
}
}